<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta http-equiv="X-UA-Compatible"content="IE=edge"><meta name="viewport"content="width=device-width, initial-scale=1.0"><title>ArtPlayer播放器</title><style type="text/css">html,body{width:100%;height:100%;padding:0;margin:0}#playerCnt{width:100%;height:100%}</style></head><body><div id="playerCnt"></div><!--引入ArtPlayer播放器的JS文件--><script src="artplayer.js"></script><script src="flv.min.js"></script><script src="hls.min.js"></script><script>var art=new Artplayer({container:document.getElementById('playerCnt'),autoSize:false,aspectRatio:true,playbackRate:true,flip:true,setting:true,theme:'#ffad00',volume:0.8,hotkey:true,autoplay:true,screenshot:true,moreVideoAttr:{crossOrigin:'anonymous',},fullscreen:true,fullscreenWeb:true,pip:true,autoMini:true,lock:true,fastForward:true,autoOrientation:true,url:parent.MacPlayer.PlayUrl,customType:{m3u8:function(video,url){if(Hls.isSupported()){const hls=new Hls();hls.loadSource(url);hls.attachMedia(video)}else{const canPlay=video.canPlayType('application/vnd.apple.mpegurl');if(canPlay==='probably'||canPlay=='maybe'){video.src=url}else{art.notice.show='不支持播放格式：m3u8'}}},},});</script></body></html>